    "tag": "Contracts",
    "summary": "Get contract items",
    "access": "character",
    "operationClass": "read",
    "requiredScopes": [
      "esi-contracts.read_character_contracts.v1"
    ],
    "requiredRoles": [],
    "authorizationScopes": [
      "esi-contracts.read_character_contracts.v1"
    ],
    "parameters": [
      {
        "name": "character_id",
        "location": "path",
        "required": true,
        "style": "form",
        "explode": true
      },
      {
        "name": "contract_id",
        "location": "path",
        "required": true,
        "style": "form",
        "explode": true
      }
    ],
    "inputSchema": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "character_id": {
          "type": "string",
          "pattern": "^(0|[1-9][0-9]*)$",
          "description": "Canonical decimal EVE identifier."
        },
        "contract_id": {
          "type": "string",
          "pattern": "^(0|[1-9][0-9]*)$",
          "description": "ID of a contract"
        }
      },
      "required": [
        "character_id",
        "contract_id"
      ]
    },
    "outputSchema": {
      "items": {
        "properties": {
          "is_included": {
            "description": "true if the contract issuer has submitted this item with the contract, false if the isser is asking for this item in the contract",
            "type": "boolean"
          },
          "is_singleton": {
            "type": "boolean"
          },
          "quantity": {
            "anyOf": [
              {
                "type": "integer",
                "minimum": -9007199254740991,
                "maximum": 9007199254740991
              },
              {
                "type": "string",
                "pattern": "^-?(0|[1-9][0-9]*)$"
              }
            ],
            "description": "Number of items in the stack"
          },
          "raw_quantity": {
            "anyOf": [
              {
                "type": "integer",
                "minimum": -9007199254740991,
                "maximum": 9007199254740991
              },
              {
                "type": "string",
                "pattern": "^-?(0|[1-9][0-9]*)$"
              }
            ],
            "description": "-1 indicates that the item is a singleton (non-stackable). If the item happens to be a Blueprint, -1 is an Original and -2 is a Blueprint Copy"
          },
          "record_id": {
            "anyOf": [
              {
                "type": "integer",
                "minimum": -9007199254740991,
                "maximum": 9007199254740991
              },
              {
                "type": "string",
                "pattern": "^-?(0|[1-9][0-9]*)$"
              }
            ],
            "description": "Unique ID for the item"
          },
          "type_id": {
            "anyOf": [
              {
                "type": "integer",
                "minimum": -9007199254740991,
                "maximum": 9007199254740991
              },
              {
                "type": "string",
                "pattern": "^-?(0|[1-9][0-9]*)$"
              }
            ],
            "description": "Type ID for item"
          }
        },
        "required": [
          "record_id",
          "type_id",
          "quantity",
          "is_singleton",
          "is_included"
        ],
        "type": "object",
        "additionalProperties": false
      },
      "type": "array"
    },
    "pagination": {
      "mode": "none",
      "defaultPages": 1,
      "maximumPages": 1,
      "metadata": null
    },
    "freshness": {
      "mode": "fixed_ttl",
      "ttlSeconds": 3600,
      "staleIfErrorSeconds": 0
    },
    "rateLimit": {
      "group": "char-contract",
      "max-tokens": 600,
      "window-size": "15m"
    },
